    for (let x = x0 + 4; x < x1 - 2; x += 10) for (let z = z0 + 4; z < z1 - 2; z += 10) if (pip(ring, x, z)) cylV(M.v, 0.3, 0.3, GY(x, z) - 0.4, y - 0.7, x, z, 6, false);
