  const u = axisOf(ring), v = [-u[1], u[0]]; let s0 = 1e9, s1 = -1e9, t0 = 1e9, t1 = -1e9; const c = ring[0];
  for (const p of ring){ const s = (p[0] - c[0])*u[0] + (p[1] - c[1])*u[1], t = (p[0] - c[0])*v[0] + (p[1] - c[1])*v[1]; s0 = Math.min(s0, s); s1 = Math.max(s1, s); t0 = Math.min(t0, t); t1 = Math.max(t1, t); }
