  GYF = ctx.gy;
  KEEPW = dec2(SD.hull).map(p => [AXY[0] + p[0], AXY[1] - p[1]]);    // the AirTrain ramps back to the data height beyond the complex's hull
  try { airtrainFix(); } catch (e){ console.error('sfo airtrain', e); }
  for (const A of SD.apron) ctx.paint(dec2(A), [206, 206, 200]);
  const t0 = performance.now();
  for (const C of SD.comp){ const kind = SD.kinds[C[0]];
    if (kind === 'itb') itbBuild(C);
    else if (STY[kind]) terminal(C, kind);
    else genericBlock(C, kind); }
  domTowers(); tower();
  for (const S of SD.st){ if (S[4]) bridges(S); standMarks(S); }
  for (const L of SD.loose) looseBridge(L);
  for (const m of SD.mast) mast(m);
  for (const k in M) flushV(g, M[k]);
  if (MK.P.length){ const geo = new THREE.BufferGeometry(); geo.setAttribute('position', new THREE.Float32BufferAttribute(MK.P, 3)); geo.setAttribute('color', new THREE.Float32BufferAttribute(MK.C, 3)); geo.computeVertexNormals(); g.add(new THREE.Mesh(geo, matMark)); }
  STATS.ms = Math.round(performance.now() - t0); STATS.tris = Object.values(M).reduce((a, V) => a + V.P.length/9, 0) + MK.P.length/9; STATS.stands = SD.st.length; STATS.airtrain = airtrainFix.n || 0;
  const late = [poolMesh(), glowPoints(), edgeLights([-900, -900, 900, 900])].filter(Boolean);
  if (late.length) PEND.push([g, late]);
